// src/pages/HomePage.js
import { useState } from 'react';
import { Link } from 'react-router-dom';
import styles from './HomePage.module.css';
import djPhoto from '../assets/dj.png';
import posts from '../data/posts';
import PostCard from '../Components/PostCard';

function HomePage() {
  const [darkMode, setDarkMode] = useState(false);
  const toggleTheme = () => setDarkMode(prev => !prev);

  return (
    <div className={darkMode ? styles['dark-mode'] : ''}>
      <header className={styles.header}>
        <h1>My Personal Portfolio</h1>
        <nav>
          <ul className={styles.navList}>
            <li><Link to="/" className={styles.active}>Home</Link></li>
            <li><Link to="/about">About</Link></li>
            <li><Link to="/contact">Contact</Link></li>
            <li><Link to="/register">Register</Link></li>
            <li><Link to="/game">Game</Link></li>
          </ul>
        </nav>
      </header>

      <button className={styles.themeToggle} onClick={toggleTheme}>
        Toggle Dark/Light
      </button>

      {/* Hero Section */}
      <section className={styles.heroWelcome}>
        <div className={styles.heroText}>
          <h2>Welcome to My Portfolio</h2>
          <p>Hi! I’m a student passionate about learning and technology. This portfolio gives a glimpse of who I am and what I do.</p>
        </div>
        <div className={styles.heroImage}>
          <img src={djPhoto} alt="Photo of the website owner" />
        </div>
      </section>

      {/* Latest Posts */}
      <section className={styles.postsGridSection}>
        <h2>Latest Posts</h2>
        <div className={styles.postsGrid}>
          {posts.map(post => (
            <PostCard
              key={post.id}
              title={post.title}
              excerpt={post.excerpt}
              date={post.date}
              tag={post.tag}
              readTime={post.readTime}
            />
          ))}
        </div>
      </section>

      <footer className={styles.footer}>
        <p>Contact: dxxxxxxxxxxx@gmail.com | Phone: 09xxxxxxx8</p>
        <p>&copy; 2026 My Personal Portfolio. All rights reserved.</p>
      </footer>
    </div>
  );
}

export default HomePage;
